import{_ as s,o as t,c as e,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"88. 更安全的替代方案（边界检查、_Static_assert 和现代 C 安全工具）","description":"The Little Book of C 中文版 — 88. 更安全的替代方案（边界检查、_Static_assert 和现代 C 安全工具）","frontmatter":{"title":"88. 更安全的替代方案（边界检查、_Static_assert 和现代 C 安全工具）","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","09-可移植与现代 C","中文"],"description":"The Little Book of C 中文版 — 88. 更安全的替代方案（边界检查、_Static_assert 和现代 C 安全工具）","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":88,"sidebarWeight":88,"alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/088-Safer Alternatives (Bounds Checking, _Static_assert, and Modern C Safety Tools)","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/088-Safer Alternatives (Bounds Checking, _Static_assert, and Modern C Safety Tools)"},"headers":[],"relativePath":"posts/c教程/zh-CN/09-可移植与现代 C/088-Safer Alternatives (Bounds Checking, _Static_assert, and Modern C Safety Tools).md","filePath":"posts/c教程/zh-CN/09-可移植与现代 C/088-Safer Alternatives (Bounds Checking, _Static_assert, and Modern C Safety Tools).md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/09-可移植与现代 C/088-Safer Alternatives (Bounds Checking, _Static_assert, and Modern C Safety Tools).md"};function i(l,a,o,d,c,r){return t(),e("div",null,[...a[0]||(a[0]=[n(`<p>[English version](/posts/c教程/en-US/09-Portable and Modern C/088-Safer Alternatives (Bounds Checking, _Static_assert, and Modern C Safety Tools))</p><p>C 赋予你权力和控制力，但也赋予你责任。由于 C 不会自动保护您免受内存错误、缓冲区溢出或类型误用的影响，因此您必须在语言和工具级别添加安全性。</p><p>本节探讨 C11 到 C23 中的现代安全功能，包括边界检查、静态断言以及编写更安全的 C 的实际习惯。</p><h4 id="步骤-1-为什么-c-语言中的安全性很重要" tabindex="-1">步骤 1. 为什么 C 语言中的安全性很重要 <a class="header-anchor" href="#步骤-1-为什么-c-语言中的安全性很重要" aria-label="Permalink to &quot;步骤 1. 为什么 C 语言中的安全性很重要&quot;">​</a></h4><p>C 之所以快，是因为它信任程序员。这意味着：</p><ul><li>它不检查数组边界。</li><li>它不会自动初始化内存。</li><li>它不会为你管理内存。</li></ul><p>这种信任既是 C 用于内核的原因，也是它导致如此多错误的原因。我们的目标不是让 C “默认安全”，而是通过设计让您对 C 的使用变得安全。</p><h4 id="步骤-2-更安全的边界处理" tabindex="-1">步骤 2. 更安全的边界处理 <a class="header-anchor" href="#步骤-2-更安全的边界处理" aria-label="Permalink to &quot;步骤 2. 更安全的边界处理&quot;">​</a></h4><p>C 语言中的一个经典错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char name[8];</span></span>
<span class="line"><span>strcpy(name, &quot;HelloWorld&quot;); // buffer overflow</span></span></code></pre></div><p>这会覆盖过去的记忆<code>name</code>并导致未定义的行为。</p><p>修复 1：使用函数的有界版本</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strncpy(name, &quot;HelloWorld&quot;, sizeof(name) - 1);</span></span>
<span class="line"><span>name[sizeof(name) - 1] = &#39;\\0&#39;;</span></span></code></pre></div><p>修复 2：使用 C11 附录 K 中引入的更安全的替代方案（如果您的编译器支持它们）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strcpy_s(name, sizeof(name), &quot;Hello&quot;);</span></span></code></pre></div><p>它们自动检查边界并返回错误代码。然而，Annex K 是可选的，因此并非所有编译器都实现它。</p><h4 id="步骤-3-小代码-安全字符串复制" tabindex="-1">步骤 3. 小代码：安全字符串复制 <a class="header-anchor" href="#步骤-3-小代码-安全字符串复制" aria-label="Permalink to &quot;步骤 3. 小代码：安全字符串复制&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char dst[8];</span></span>
<span class="line"><span>    strncpy(dst, &quot;Example&quot;, sizeof(dst) - 1);</span></span>
<span class="line"><span>    dst[sizeof(dst) - 1] = &#39;\\0&#39;;</span></span>
<span class="line"><span>    printf(&quot;Safe copy: %s\\n&quot;, dst);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc safe_copy.c -o safe_copy -Wall -Wextra -O2</span></span></code></pre></div><p>这<code>-Wall -Wextra</code>标志可以尽早警告可疑行为，这是最好的“安全工具”之一。</p><h4 id="步骤-4-static-assert-编译时检查" tabindex="-1">步骤 4. _Static_assert：编译时检查 <a class="header-anchor" href="#步骤-4-static-assert-编译时检查" aria-label="Permalink to &quot;步骤 4. _Static_assert：编译时检查&quot;">​</a></h4><p>在C11中引入，<code>_Static_assert</code>让您可以在程序编译之前验证条件。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_Static_assert(sizeof(int) == 4, &quot;This code requires 32-bit int&quot;);</span></span></code></pre></div><p>如果条件失败，编译将停止并显示一条明确的消息。</p><p>您可以将其用于：</p><ul><li>检查结构布局</li><li>确保字体大小</li><li>验证数组长度</li><li>强制不变量</li></ul><h4 id="步骤-5-更安全的整数运算" tabindex="-1">步骤 5. 更安全的整数运算 <a class="header-anchor" href="#步骤-5-更安全的整数运算" aria-label="Permalink to &quot;步骤 5. 更安全的整数运算&quot;">​</a></h4><p>整数溢出是 C 中未定义的行为。示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 2147483647 + 1; // overflow</span></span></code></pre></div><p>更安全的选择：</p><p>使用<code>unsigned</code>有意包装时的类型。</p><p>使用编译器标志：</p><p>-<code>-ftrapv</code>(GCC/Clang)：溢出陷阱。 -<code>-fsanitize=undefined</code>：运行时检测溢出。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -fsanitize=undefined -O2 -g check.c -o check</span></span></code></pre></div><p>这将在发生溢出时中止您的程序。</p><h4 id="步骤-6-空指针和资源安全" tabindex="-1">步骤 6. 空指针和资源安全 <a class="header-anchor" href="#步骤-6-空指针和资源安全" aria-label="Permalink to &quot;步骤 6. 空指针和资源安全&quot;">​</a></h4><p>始终检查返回值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *f = fopen(&quot;data.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>if (!f) {</span></span>
<span class="line"><span>    perror(&quot;Failed to open file&quot;);</span></span>
<span class="line"><span>    return 1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>对于动态内存：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char *p = malloc(100);</span></span>
<span class="line"><span>if (!p) {</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Out of memory\\n&quot;);</span></span>
<span class="line"><span>    exit(1);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>并且始终<code>free()</code>完成后。</p><h4 id="步骤-7-安全工具" tabindex="-1">步骤 7. 安全工具 <a class="header-anchor" href="#步骤-7-安全工具" aria-label="Permalink to &quot;步骤 7. 安全工具&quot;">​</a></h4><p>现代编译器和工具可帮助您及早发现错误：</p><table tabindex="0"><thead><tr><th>工具</th><th>目的</th></tr></thead><tbody><tr><td>地址消毒剂（<code>-fsanitize=address</code>)</td><td>检测缓冲区溢出、释放后使用</td></tr><tr><td>未定义行为Sanitizer (<code>-fsanitize=undefined</code>)</td><td>检测整数和类型错误</td></tr><tr><td>瓦尔格林德</td><td>检查内存泄漏和无效访问</td></tr><tr><td>铿锵整齐</td><td>静态分析和风格检查</td></tr><tr><td>cpp检查</td><td>用于 C/C++ 的便携式静态分析器</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clang -fsanitize=address safe.c -o safe</span></span>
<span class="line"><span>./safe</span></span></code></pre></div><p>如果存在错误，您将获得详细的内存跟踪。</p><h4 id="步骤-8-结构和对齐检查" tabindex="-1">步骤 8. 结构和对齐检查 <a class="header-anchor" href="#步骤-8-结构和对齐检查" aria-label="Permalink to &quot;步骤 8. 结构和对齐检查&quot;">​</a></h4><p>序列化或使用硬件时，意外的填充可能会导致问题。您可以在编译时断言布局：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stddef.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>struct Packet {</span></span>
<span class="line"><span>    char type;</span></span>
<span class="line"><span>    int id;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>_Static_assert(offsetof(struct Packet, id) == 4, &quot;Alignment mismatch&quot;);</span></span></code></pre></div><p>这可以确保您对内存布局的假设是正确的。</p><h4 id="步骤-9-防御宏和编译标志" tabindex="-1">步骤 9. 防御宏和编译标志 <a class="header-anchor" href="#步骤-9-防御宏和编译标志" aria-label="Permalink to &quot;步骤 9. 防御宏和编译标志&quot;">​</a></h4><p>使用编译时选项保护自己：</p><table tabindex="0"><thead><tr><th>旗帜</th><th>目的</th></tr></thead><tbody><tr><td><code>-Wall -Wextra</code></td><td>启用重要警告</td></tr><tr><td><code>-Werror</code></td><td>将警告视为错误</td></tr><tr><td><code>-Wconversion</code></td><td>隐式类型转换警告</td></tr><tr><td><code>-fsanitize=address</code></td><td>检测内存安全问题</td></tr><tr><td><code>-D_FORTIFY_SOURCE=2</code></td><td>添加运行时缓冲区检查 (glibc)</td></tr><tr><td><code>-fstack-protector-strong</code></td><td>检测堆栈损坏</td></tr><tr><td><code>-O2</code></td><td>安全优化，无需进行危险的转换</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -Wall -Wextra -Werror -O2 -fstack-protector-strong -D_FORTIFY_SOURCE=2 main.c -o main</span></span></code></pre></div><h4 id="步骤-10-小代码-使用静态断言和消毒剂" tabindex="-1">步骤 10. 小代码：使用静态断言和消毒剂 <a class="header-anchor" href="#步骤-10-小代码-使用静态断言和消毒剂" aria-label="Permalink to &quot;步骤 10. 小代码：使用静态断言和消毒剂&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>struct Data {</span></span>
<span class="line"><span>    int id;</span></span>
<span class="line"><span>    char name[16];</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>_Static_assert(sizeof(struct Data) &lt;= 32, &quot;Struct too large&quot;);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    struct Data d = {42, &quot;C Safety&quot;};</span></span>
<span class="line"><span>    printf(&quot;%d %s\\n&quot;, d.id, d.name);</span></span>
<span class="line"><span>    char buf[8];</span></span>
<span class="line"><span>    strncpy(buf, &quot;Safe&quot;, sizeof(buf) - 1);</span></span>
<span class="line"><span>    buf[sizeof(buf) - 1] = &#39;\\0&#39;;</span></span>
<span class="line"><span>    printf(&quot;Buffer: %s\\n&quot;, buf);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -Wall -Wextra -fsanitize=address -O2 safe_program.c -o safe_program</span></span></code></pre></div><p>如果内存安全受到侵犯，该程序将中止，并在测试期间为您提供即时反馈。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>安全不会让你的代码变慢，它会让你的软件值得信赖。尽管 C 为您提供了锋利的工具，但静态检查、编译器警告和运行时清理程序的组合可以使您的程序对于生产系统而言足够强大。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>1.添加<code>_Static_assert</code>检查您的结构和常量。 2. 编译<code>-Wall -Wextra -Werror</code>并修复所有警告。 3. 使用AddressSanitizer 捕获越界错误。 4. 在 Valgrind 下测试您的程序是否存在泄漏。 5. 尝试将相同的错误代码编写两次，一次是原始代码，一次是安全代码，然后比较行为。</p><p>接下来，您将探索现代 C 风格，如何在 C23 时代编写清晰、可维护且惯用的代码。</p>`,69)])])}const g=s(p,[["render",i]]);export{u as __pageData,g as default};
